      bowlAnim: cs.animationName,
      steamCount: steam.length,
      steamAnim: getComputedStyle(steam[0]).animationName,
      hasSvg: !!document.querySelector('svg'),
      bodyKids: document.body.children.length,
      textContent: document.body.innerText.trim().length
    };
  });
  console.log('page info', JSON.stringify(info));

