    viewport: { width: 1280, height: 800 },
    reducedMotion: 'reduce'
  });
  const page2 = await ctx2.newPage();
  await page2.goto('http://<LAN_IP>:8765/index.html', { waitUntil: 'networkidle' });
  await page2.waitForTimeout(900);
  const reduced = await page2.evaluate(() => {
    const bowl = document.getElementById('bowl');
    const plume = document.querySelector('.steam-plume');
    return {
      bowlAnim: getComputedStyle(bowl).animationName,
      steamAnim: getComputedStyle(plume).animationName,
      steamOpacity: getComputedStyle(plume).opacity
    };
  });
  console.log('reduced motion', JSON.stringify(reduced));
  await page2.screenshot({ path: '<TMP>/ramen-shot-reduced.png' });
  await browser.close();
  console.log('screenshots ok');
})().catch(e => { console.error(e); process.exit(1); });
EOF

