const { chromium } = require('<TMP>/ramen-verify/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: process.env.CHROME || '<HOME>/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',
    args: ['--no-sandbox','--disable-gpu']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await page.goto('http://<LAN_IP>:8765/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);

  const center = await page.evaluate(() => {
    const b = document.getElementById('bowl');
    return { px: b.style.getPropertyValue('--px'), py: b.style.getPropertyValue('--py'),
             mx: document.getElementById('ambience').style.getPropertyValue('--mx') };
  });

  await page.mouse.move(100, 100);
  await page.waitForTimeout(700);
  const left = await page.evaluate(() => {
    const b = document.getElementById('bowl');
    return {
      px: parseFloat(b.style.getPropertyValue('--px')),
      py: parseFloat(b.style.getPropertyValue('--py')),
      rx: parseFloat(b.style.getPropertyValue('--rx')),
      ry: parseFloat(b.style.getPropertyValue('--ry')),
      mx: document.getElementById('ambience').style.getPropertyValue('--mx'),
      cursorVisible: document.getElementById('cursor').classList.contains('visible')
    };
  });

  await page.mouse.move(1180, 700);
  await page.waitForTimeout(700);
  const right = await page.evaluate(() => {
    const b = document.getElementById('bowl');
    return {
      px: parseFloat(b.style.getPropertyValue('--px')),
      py: parseFloat(b.style.getPropertyValue('--py')),
      mx: document.getElementById('ambience').style.getPropertyValue('--mx')
    };
  });

  console.log('center', center);
  console.log('left', left);
  console.log('right', right);
  const moved = left.px < -2 && right.px > 2 && left.cursorVisible;
  console.log(moved ? 'PASS: parallax + cursor respond' : 'FAIL: interaction weak');
  await browser.close();
  process.exit(moved ? 0 : 1);
})().catch(e => { console.error(e); process.exit(1); });
EOF

